def cmd_blocked_on_land(args: argparse.Namespace) -> None:
    """T-10792 — resolve the TWO accepted reason forms into the one `args.reason` the command core
    reads. The bare doctrine form `blocked-on-land T-XXXX <reason...>` arrives as positional words;
    `--reason` is the equivalent flag and WINS when both are given (an explicit flag is the more
    deliberate statement). Joining happens HERE, at the parser edge, so the core keeps the single
    `args.reason` contract its sibling `task refuse` already uses."""
    words = " ".join(getattr(args, "reason_words", None) or []).strip()
    args.reason = (getattr(args, "reason_flag", None) or "").strip() or words
    return worktree_mod.cmd_blocked_on_land(args, REPO_ROOT=REPO_ROOT, _append_event=_append_event, _die=_die, _load_task_for_transition=_load_task_for_transition, _live_task_worktrees=_live_task_worktrees, _branch_carried_claim=_branch_carried_claim)
def _git_grep_present(token: str) -> bool:
    """SPEC-0166: is a code-site token still present in today's CODE? A git-grep (fixed-string,
    tracked files under REPO_ROOT) EXCLUDING the governance / journal / test dirs — a token that
    lives only in a task card, spec or test fixture must NOT read as 'present in code'. Fail-closed:
    any non-zero git exit (no match, or a degenerate repo) reads as ABSENT (the conservative
    premise direction — a card whose site cannot be confirmed present is not auto-verified)."""
    if not token:
        return False
    excludes = [f":(exclude){d}" for d in
                ("tasks", "specs", "decisions", "plans", "ideas", "lessons",
                 "scenarios", "errors", "graph", "tests", "events.jsonl", ".yitc")]
    r = _run_git_cap(["grep", "-I", "-F", "-q", "-e", token, "--", "."] + excludes, REPO_ROOT)
    return r.returncode == 0
