def _view_overdue_recheck(today=None) -> dict:
    # T-12076 — the two corpora the deferred-probe FIRING predicate needs beyond this repo's own
    # cards: the terminal coordination ids and the event classes the journal carries (with each
    # class's latest ts, for an `@after=` anchor). Injected BEST-EFFORT and OPTIONAL by construction:
    # the leaf derives the terminal TASK ids from the glob it already makes, so an `awaits T-NNNN`
    # moment resolves with no injection at all, and an unreadable journal or coordination store
    # degrades to "that class has not arrived" — the ARMED direction, which keeps the probe visible
    # as pending rather than silently discharging it.
    _cross: frozenset = frozenset()
    _seen: set = set()
    _latest: dict = {}
    try:
        _cross = _terminal_cross_ids()
    except Exception:
        pass
    try:
        # The SAME fold key every other followup reader uses — the effective events path plus the
        # SEGMENT-AWARE physical reader (SPEC-0190 rule 4; an un-injected reader would silently see
        # the live segment alone). Inside `_debt_echo_lines`' `fold_memo()` scope this is therefore
        # served from the single shared parse and adds NO second walk (T-12031); the memo stores the
        # out-parameter fills, so `_seen` / `_latest` are populated either way.
        followup_mod._fold(_followup_events_path(),
                           _segment_lines=journal_mod.segment_fold_lines,
                           seen_event_types=_seen, latest_event_ts=_latest)
    except Exception:
        pass
    return views._view_overdue_recheck(today, TASKS_DIR=TASKS_DIR, _read_yaml=_read_yaml,
                                       _terminal_cross_ids=_cross, _seen_event_types=_seen,
                                       _latest_event_ts=_latest)
