    return worktree_mod.cmd_work_commit(args, _append_event=_append_event, _commit_worktree=_commit_worktree, _die=_die, _governing_contract_for=_governing_contract_for, _settle_journal_receipt=_settle_journal_receipt, REPO_ROOT=REPO_ROOT)


