def _reject_id_shaped_plan_slug(slug: str) -> None:
    """T-0193 (audit-post F1): plan audit artifacts share the decisions/<id>-audit-*.yaml namespace
    with task/decision audits, so refuse a plan slug shaped like a task/decision id (`X-NNNN`) — a
    dumb fail-closed guard that makes the namespace collision structurally impossible (defense-in-
    depth; plan slugs are kebab-case so this never fires in practice). Called at the audit-plan
    entry AND the close gate. (T-0527/SPEC-0052: the displacement-retention drain only moves CLOSED
    *task* audits — `T-NNNN-audit-*.yaml` — into decisions/archive/; plan-gate audits are written for
    in-flight plans and stay in decisions/, so this id-shape namespace guard is unaffected by the move.)"""
    if re.match(r"^[A-Za-z]-\d{4,}$", slug or ""):
        _die(f"plan slug {slug!r} collides with a task/decision id shape (X-NNNN) — rename the plan; "
             "plan + task/decision audits share the decisions/<id>-audit-*.yaml namespace.")


def _plan_specs(slug: str) -> list:
    """ONE corpus builder (T-0193 Part B; broadened T-0256). The plan's realization spec-corpus =
    every specs/SPEC-*.yaml the plan REALIZED: born by the plan (`proposed_by==slug`, the plan-accept
    carrier) OR activated by one of the plan's implementing tasks (`activation_owner_task` ∈ the ids of
    `_plan_tasks(slug)` — tasks linked by `decomposed_from:slug` OR `cites:slug`, the T-9152 union
    carrier). The
    proposed_by-only rule was too narrow: a reorg/task-only plan whose realizing specs are born
    work-first by its tasks (proposed_by==<task>) or activated by a task (a parent-born spec) had an
    EMPTY corpus, so `audit post --plan` graded nothing and the close gate auto-skipped (the part-i-b
    incident, T-0247). Broader closed_into/supersedes traversal stays deferred to Part D. Returns
    sorted, de-duped [(sid, status)]. Reused by the realization block, the audit-post corpus_signature,
    AND the plan close gate (P5, single source)."""
    task_ids = {tid for tid, _st in _plan_tasks(slug)}   # implementing tasks (decomposed_from OR cites:slug — T-9152 union)
    out = {}
    for p in state.scan_specs(SPECS_DIR):   # SPEC-* glob excludes _template.yaml
        d = _read_yaml(p)
        if not isinstance(d, dict):
            continue
        if d.get("proposed_by") == slug or d.get("activation_owner_task") in task_ids:
            out[d.get("id") or p.stem] = d.get("status")   # dedup by id (a work-first spec matches both)
    return sorted(out.items())


def _plan_tasks(slug: str) -> list:
    """Part D/1 (T-0209; re-keyed T-9152): the plan's implementing tasks = every tasks/T-*.yaml that
    is linked to the plan by EITHER carrier — `decomposed_from == slug` (the governed SPEC-0070 §5 cut
    marker, the PRIMARY carrier) OR `slug` as an EXACT element of its `cites:` list (`slug in cites` —
    list-membership equality, NOT substring; backward-compat — the bare plan slug is exactly what `plan
    close` reverse-links into cites: via _link_plan_into_targets). Returns sorted [(tid, status)].

    T-9152 — WHY the union: `task file --decomposed-from` writes ONLY `decomposed_from`, it does NOT
    auto-add `cites:<plan>`, so a DECOMPOSED-ONLY cut card carries no `cites:<plan>` and was invisible
    to the old cites-only corpus → `audit post --plan` RED 'no implementing task' on a fully-realized
    decomposed plan (the live reconcile-cross-project-routing-filing-moment-surf incident). The
    finalization corpus is the BROAD relation "tasks that implement/activate the plan"; a decomposed
    cut card IS such a task, so it must count. This BROADENS the corpus by ADDING `decomposed_from` —
    it does NOT re-derive cut MEMBERSHIP from `cites` (the inverse T-0678 defect): the NARROW
    cut-fidelity member-set (`_plan_cut_cards` → `_plan_card_set_fingerprint`) stays `decomposed_from`-
    ONLY and NON-SUBSTITUTABLE (SPEC-0070 §5 / SPEC-0034). Read from the source task YAML, NOT the
    derived graph `tasks_citing` index, which keys on T-/D-/SPEC- ids only (never a kebab plan slug;
    _id_from_artifact_ref) so it never holds a plan→task edge (P5: read the canonical fields).

    T-10927 — a caller asking this once PER PLAN re-read the whole corpus per plan (O(N*M)). When a
    `plan._plan_link_index_scope()` is OPEN, the same union is served from the ONE sweep that scope
    already did; with NO scope open this falls through to the original sweep, byte-identically."""
    index = plan_mod._plan_link_index()
    if index is not None:
        return sorted((tid, st) for tid, st, _rt, _cls in index.get(slug, []))
    out = []
    for p in state.scan_tasks(TASKS_DIR):   # T-* glob excludes _template.yaml
        d = _read_yaml(p)
        if isinstance(d, dict) and (d.get("decomposed_from") == slug or slug in (d.get("cites") or [])):
            out.append((d.get("id") or p.stem, d.get("status")))
    return sorted(out)


def _plan_cut_cards(slug: str) -> list:
    return plan_mod._plan_cut_cards(slug, TASKS_DIR=TASKS_DIR, _read_yaml=_read_yaml)


def _plan_link_index_scope():
    """T-10927 host wrapper — injects the host globals at call time (so a `-C` REPO_ROOT rebind and a
    `monkeypatch.setattr(yitc, '_read_yaml', …)` stay honoured, the Design-B re-export contract)."""
    return plan_mod._plan_link_index_scope(TASKS_DIR=TASKS_DIR, _read_yaml=_read_yaml)


def _plan_task_carrier(slug: str) -> list:
    """Part D/1 (T-0209): the canonical task-side carrier value = sorted ["<tid>:<status>", ...] for
    every task LINKED to the plan (decomposed_from OR cites — the `_plan_tasks` union, T-9152).
    Deterministic (sorted) AND status-bearing, so the close-gate freshness
    check catches BOTH membership change AND a task status regression (audit-pre F1/F2) — mirrors the
    spec-side corpus_signature `sid:status` encoding. ONE function, two readers (cmd_audit writes it
    into the saved YAML; _require_plan_finalization_ready re-derives + compares — P5, single source)."""
    return [f"{tid}:{st}" for tid, st in _plan_tasks(slug)]


def _plan_retire_on_proof(slug: str) -> list:
    """T-0326: the plan's RETIRE-ON-PROOF tasks = tasks LINKED to the plan and carrying a non-empty
    `return_trigger` (deferred-by-condition per the task model — "retire the OLD mechanism once the
    NEW is proven 100%"). REUSES the existing parked/return_trigger task fields — NO new task class
    or flag (CHARTER §P1). The retire-on-proof SET is defined by the `return_trigger` PRESENCE, not by
    a specific trigger value (audit-pre F1: the owner model defines retire-on-proof as "a parked linked
    task WITH a return_trigger"; there is no canonical value enum) and NOT by being currently `parked`
    (audit-pre F2: keying the EXIT requirement on still-parked would let a retire-on-proof task moved
    parked→ready/blocked-but-not-done slip the realized gate). Returns sorted [(tid, status)]. ONE
    source, TWO readers: the postcheck ENTRY gate exempts the currently-`parked` members (they soak
    during postcheck); the `realized` EXIT gate requires EVERY member terminal (old retired).

    T-10952 (X-0818) — WHY the LINK is the `_plan_tasks` UNION (`decomposed_from == slug` OR `slug in
    cites`), not `cites` alone: this predicate defines an EXEMPTION over the `_plan_tasks` membership,
    and that membership has been the union since T-9152 (because `task file --decomposed-from` writes
    ONLY `decomposed_from` and never auto-adds `cites:<plan>`). Keyed on `cites` alone, a card created
    by the governed cut path and then parked WITH a `return_trigger` was structurally UNEXEMPTABLE — it
    entered the blocking set via `decomposed_from` and could never enter the exemption set — so `plan
    stage postcheck` refused while its own refusal text said parked retire-on-proof tasks are excepted
    (observed live by boomrocket on plan sandbox-data-neutralize-and-generated-spike-compos). A set and
    its exemption must read the SAME carrier. This does NOT touch the NARROW cut-fidelity member-set
    (`_plan_cut_cards` → `_plan_card_set_fingerprint`), which stays `decomposed_from`-ONLY and
    NON-SUBSTITUTABLE (SPEC-0070 §5 / SPEC-0034) — that asymmetry is DELIBERATE; do not "align" it.

    T-10927 — same reuse as `_plan_tasks`: served from an OPEN `plan._plan_link_index_scope()` (which
    carries the `return_trigger` PRESENCE flag, the only extra field this predicate adds on top of the
    link union), else the original full sweep, byte-identically."""
    index = plan_mod._plan_link_index()
    if index is not None:
        return sorted((tid, st) for tid, st, has_trigger, _cls in index.get(slug, []) if has_trigger)
    out = []
    for p in state.scan_tasks(TASKS_DIR):   # T-* glob excludes _template.yaml
        d = _read_yaml(p)
        if (isinstance(d, dict)
                and (d.get("decomposed_from") == slug or slug in (d.get("cites") or []))
                and str(d.get("return_trigger") or "").strip()):
            out.append((d.get("id") or p.stem, d.get("status")))
    return sorted(out)


def _retire_on_proof_unresolved(slug: str) -> list:
    """T-0613 — the SINGLE shared predicate for "which retire-on-proof members are NOT yet resolved".
    A member is RESOLVED when its status is a TERMINAL close (`done` OR `wont-do` —
    RETIRE_ON_PROOF_RESOLVED_STATUSES); every non-terminal status (parked/ready/blocked/in-progress)
    is UNRESOLVED and blocks (the anti-slip intent: a parked→ready move must not masquerade as
    resolved). ONE source for BOTH readers — the `realized` EXIT gate
    (_require_plan_retire_on_proof_resolved) and the postcheck-plans-readiness lens clause (b) — so
    they agree byte-for-byte (P5, no drift #10). Returns sorted [(tid, status)] (already sorted —
    _plan_retire_on_proof returns sorted) of the UNRESOLVED members."""
    return [(tid, stt) for tid, stt in _plan_retire_on_proof(slug)
            if stt not in RETIRE_ON_PROOF_RESOLVED_STATUSES]




# ---------------------------------------------------------------------------
# Plan-finalization-not-forgotten trigger (T-0227). Root cause: `decision finalize` had no
# auto-trigger and relied on AI memory → Part F was forgotten at `accepted`. Doctrine (D-0050):
# ride the discipline on a VERB (`task close`), not AI memory — NO cron/daemon/autopilot (CHARTER
# non-goals). Two layers share ONE citing-task computation (P5, no drift): PUSH = a non-blocking
# WARN + task_closed payload field at close; PULL = the `plans-pending-finalization` saved view.
# ---------------------------------------------------------------------------

def _plan_open_citing_tasks(slug: str, exclude_tid: str | None = None) -> list:
    """Open (TASK_OPEN_STATUSES) tasks citing the plan, minus exclude_tid. Reuses _plan_tasks (the
    canonical cites:<plan> read, P5) — done/parked/wont-do are filtered out (they are not pending
    realization work). exclude_tid lets the close path ask "any OTHER open task?" independently of
    whether the closing task's `done` has been persisted yet. Returns sorted [(tid, status)]."""
    return [(tid, st) for tid, st in _plan_tasks(slug)
            if st in TASK_OPEN_STATUSES and tid != exclude_tid]








def _plan_realization_block(slug: str) -> str:
    return audit._plan_realization_block(slug, SPEC_ABANDONED_TERMINAL=SPEC_ABANDONED_TERMINAL, _find_task_yaml=_find_task_yaml, _plan_retire_on_proof=_plan_retire_on_proof, _plan_specs=_plan_specs, _plan_tasks=_plan_tasks)


def _plan_corpus_signature(slug: str, plan_body: str) -> str:
    """Freshness signature for the plan-finalization gate (T-0193; audit-pre F0 absorbed): binds the
    audit to BOTH the plan body AND its spec corpus — EITHER changing invalidates the audit-post.
    sha256(plan content_hash + sorted '<sid>:<status>' corpus). Mirrors `plan check`'s content_hash."""
    corpus = ";".join(f"{sid}:{st}" for sid, st in _plan_specs(slug))
    basis = f"{_plan_content_hash(plan_body)}|{corpus}"
    return hashlib.sha256(basis.encode("utf-8")).hexdigest()


