# Re-export → audit.decision_audit_prompt_parts (T-9248): a pure (overlay, body) builder, called only
# by the moved _build_audit_prompt; kept under the historical name for provenance.
_lazy_alias("_decision_audit_prompt_parts", "audit", "decision_audit_prompt_parts")


def _latest_event_for(task_id: str, event_type: str) -> dict | None:
    """Return the LAST events.jsonl entry matching task_id + type (physical-last, the most
    recent append), or None. Used by task audit-post to surface the Stage-6 `tests_passed`
    evidence to the auditor (T-0123). Read-only; tolerant of malformed lines."""
    import json as _json
    if not EVENTS_PATH.exists():
        return None
    found = None
    for line in journal_mod.segment_lines(EVENTS_PATH):  # T-11444: segment-aware fold (SPEC-0190 r4)
        if not line.strip():
            continue
        try:
            obj = _json.loads(line)
        except ValueError:
            continue
        if obj.get("task_id") == task_id and obj.get("type") == event_type:
            found = obj
    return found


# T-0141: the auditor REVIEWS, it does not act. An agentic auditor on a docs/handbook-edit plan
# tried to APPLY the edit, hit its read-only sandbox, and ABORTed instead of reviewing (T-0139
# incident 2026-05-31). This universal clause (rides every audit prompt) scopes that out — the
# generalization of the audit-post tests-specific D-0043 clause. Provider-neutral (P4b).

# E-0008 fix-1 (T-0258): deliver the mode-a vs mode-b absorption discipline AT AUDIT TIME, in EVERY
# audit prompt (pre + post). Without it, the session pushes PASSABLE findings through mode-a (re-audit)
# and falsely hits the 2-pass ceiling on sound work. Canonical home: LIFECYCLE §Stage 4 + SPEC-0016.


def _forecast_touched_files(task: dict) -> list:
    return audit._forecast_touched_files(task, _anchor_file=_anchor_file, REPO_ROOT=REPO_ROOT)


def _diff_touched_files(diff_text: str) -> list:
    """T-0444 audit-POST: every file named by a unified diff. Parse the FULL `diff --git a/<p1> b/<p2>`
    header — it is present for EVERY shape (rename/copy/delete/new-file/pure-mode-change/binary), so
    taking BOTH paths covers the cases a `+++ b/` scan alone would miss (YELLOW-pre [1]); `+++ b/` /
    `--- a/` stay as a secondary fallback for a malformed header. Pure f(diff); sorted/deduped;
    `/dev/null` dropped (add/delete sentinel)."""
    if not diff_text:
        return []
    out: set = set()
    for ln in diff_text.splitlines():
        if ln.startswith("diff --git "):
            m = re.match(r"diff --git a/(.+?) b/(.+)$", ln)
            if m:
                out.add(m.group(1).strip())
                out.add(m.group(2).strip())
        elif ln.startswith("+++ b/"):
            out.add(ln[6:].strip())
        elif ln.startswith("--- a/"):
            out.add(ln[6:].strip())
    out.discard("/dev/null")
    return sorted(p for p in out if p and p != "dev/null")


def _spec_coverage_section(task: dict, stage: str, diff: "str | None", stale_sink=None) -> str:
    """T-0444: the derived `### Spec coverage of touched files` block appended to a TASK audit prompt.
    Pure f(graph, plan/diff); REPORT-NOT-BLOCK (GRAPH §"NOT a validation layer" — the auditor judges,
    the section never gates). Touched files = `_forecast_touched_files` (pre) | `_diff_touched_files`
    (post). Per file: the governing ACTIVE specs (graph `code_to_specs`, status-filtered) OR a
    `(no governing spec)` marker; PLUS the symbol-level drift flags from `_changed_anchor_spec_drift`
    (touched-scoped, active-only — it DERIVES drift from each active spec's `implements:` anchor blob
    AS OF the spec's last-touch commit vs the current tree, no change-map needed). This is what lets
    the external auditor answer the two coverage questions: (1) code touched with NO spec — justified
    spec-less or a doc gap? (2) a touched `implements:` anchor whose spec is NOT updated — drift?

    `stale_sink` (T-11977, SPEC-0036 §Packet preview): an optional list this function appends
    `(file, SPEC-ID)` pairs to for every possibly-stale anchor it ALREADY found — the same
    `_changed_anchor_spec_drift` walk, handed back instead of walked twice, so the `--preview`
    readiness block reports stale anchors without re-parsing the section rendered here. Purely
    additive: the returned string is byte-unchanged whether or not a sink is supplied."""
    if stage not in ("pre", "post"):
        return ""
    touched = _forecast_touched_files(task) if stage == "pre" else _diff_touched_files(diff or "")
    header = ("### Spec coverage of touched files\n\n"
              "(derived f(graph, " + ("plan-forecast" if stage == "pre" else "shipped diff") + ") — "
              "REPORT-NOT-BLOCK; the graph is not a validator. Use this to answer the two coverage "
              "questions in the overlay above.)\n")
    if not touched:
        # ALWAYS render for a task pre/post (audit-post YELLOW [0]): the section rides EVERY task
        # prompt + carries the two questions even when no touched file is forecast/parsed — never omit.
        return header + ("\n(no touched files "
                         + ("forecast from the plan" if stage == "pre" else "parsed from the diff")
                         + " — coverage N/A this run; the two coverage questions above still apply to "
                         "any code you identify in the plan/diff.)\n")
    if not GRAPH_PATH.exists():
        return header + "\n(graph index absent — run `yitc-v2 graph build`; coverage unavailable this run)\n"
    index = _read_yaml(GRAPH_PATH) or {}
    c2s = index.get("code_to_specs", {}) or {}
    specs = index.get("specs", {}) or {}
    drift: dict = {}
    for d in _changed_anchor_spec_drift(touched, {}):
        _dfile = _anchor_file(d.get("anchor", ""))
        drift.setdefault(_dfile, []).append(
            f"{d.get('spec')} @ {d.get('anchor')}: {d.get('warn')}")
        if stale_sink is not None:
            # Report-only capture — a sink must never break the section it rides on.
            try:
                stale_sink.append((_dfile, str(d.get("spec") or "")))
            except Exception:      # noqa: BLE001 — observation only
                pass
    tid = str(task.get("id") or "")
    lines = [header]
    any_activating = False
    for f in touched:
        linked = c2s.get(f, [])
        govs = sorted(s for s in linked if (specs.get(s) or {}).get("status") == "active")
        # T-10707 (X-0556): a spec THIS task activates is still `proposed` at audit time — the
        # proposed→active write is this task's own `task close` (GRAPH §Spec lifecycle). Rendering
        # it as `(no governing spec)` made every activation-owner task read as code-with-no-spec
        # and false-RED at the auditor. Named EXPLICITLY (activation_owner_task == this task id —
        # SPEC-0005 §5), so another task's proposed spec is still not rendered.
        activating = sorted(s for s in linked
                            if tid and (specs.get(s) or {}).get("status") == "proposed"
                            and (specs.get(s) or {}).get("activation_owner_task") == tid)
        any_activating = any_activating or bool(activating)
        entries = govs + [f"{s} (proposed — ACTIVATING at THIS task's closure)" for s in activating]
        lines.append(f"- `{f}` — governed by: {', '.join(entries)}" if entries
                     else f"- `{f}` — (no governing spec)")
        for dl in drift.get(f, []):
            lines.append(f"    ⚠ possibly-stale: {dl} — was that spec updated in THIS change? if not, "
                         f"justify (deliberate / unrelated symbol) or update the spec")
    if any_activating:
        lines.append("\n(a spec marked ACTIVATING is `proposed` NOW by design: `proposed → active` is "
                     "written by THIS task's own `task close` at Stage 9 (GRAPH §Spec lifecycle) — the "
                     "code is governed, the activation simply follows the ship. Read that as the NORMAL "
                     "ordering, NOT as a doc gap or a missing spec.)")
    lines.append("")
    return "\n".join(lines)


# T-9315 (friction F-014 / X-0023): the governing scenario contract surfaced into a TASK audit prompt
# ONLY when a scenario file is in the touched set. SPEC-0076 is the scenario DOCTRINE — the governing
# contract; the prompt cites + EMBEDS its body (single-SoT — the auditor judges against the real spec,
# never a restated rule). The recurring false-positive this closes: a routine -C audit flagged a
# `(ungoverned)` step non-conformant against a kernel §5 rule the prompt never surfaced.
SCENARIO_CONTRACT_SPEC = "SPEC-0076"


def _scenario_contract_section(task: dict, stage: str, diff: "str | None") -> str:
    """T-9315: when the planned (pre) / shipped (post) diff touches `scenarios/`, embed the GOVERNING
    scenario contract (SPEC-0076 — the scenario doctrine) so the external auditor judges the scenario
    against the REAL rules (zero-normative; the step-annotation obligation is PER-AUTHORED-item, NOT a
    coverage/completeness mandate; a `(ungoverned)` step is a SANCTIONED marker, never a defect) instead
    of inventing a coverage rule (the F-014 / X-0023 false-positive). The contract file resolves with the
    T-0860/T-9313 ENGINE-content fallback (`_find_spec_path(..., engine_fallback=True)`), so a -C consumer
    whose own corpus lacks the kernel spec still gets it from the engine install path. Task pre/post only
    (decision/plan/adhoc/consult unaffected); REPORT-ONLY (never a gate); omitted when no scenario file is
    touched. Mirrors `_spec_coverage_section`'s touched-files derivation."""
    if stage not in ("pre", "post"):
        return ""
    touched = _forecast_touched_files(task) if stage == "pre" else _diff_touched_files(diff or "")
    if not any(_norm_repo_path(p).startswith("scenarios/") for p in touched):
        return ""
    path = _find_spec_path(SCENARIO_CONTRACT_SPEC, engine_fallback=True)
    if path is None or not path.exists():
        return ""
    body = (_read_yaml(path) or {}).get("body") or ""
    if not body.strip():
        return ""
    return (
        f"### Scenario doctrine — GOVERNING CONTRACT ({SCENARIO_CONTRACT_SPEC})\n\n"
        "This change touches `scenarios/`. A scenario is a ZERO-NORMATIVE, descriptive composition of\n"
        "specs into a user-path; it governs NOTHING and is held to the contract below, NOT to a\n"
        "coverage/completeness standard. Judge the scenario AGAINST THIS CONTRACT — do not invent rules:\n"
        "  - The step-annotation obligation is PER-AUTHORED-item, NOT a coverage mandate (§5): the\n"
        "    ABSENCE of a step or an error-branch is NEVER itself a defect or a review-fail.\n"
        "  - A step marked `(ungoverned)` is a SANCTIONED marker for a deliberately ungoverned step\n"
        "    (a recognized non-goal) — it is CONFORMANT, never a finding.\n"
        "  - The real defect to catch is the OPPOSITE: scenario-resident NORMATIVE language (a\n"
        "    `must/always/never` that is an enforceable rule belongs in a spec/FSM/test, §2), not a\n"
        "    missing or ungoverned annotation.\n\n"
        f"The governing contract (verbatim {SCENARIO_CONTRACT_SPEC} body):\n\n```\n{body.rstrip()}\n```\n"
    )


def _build_audit_prompt(task: dict, stage: str, diff: str | None, extra: str | None,
                        target_kind: str = "task", focus: str = None,
                        event_emit_only: bool = False, serve_deploy: bool = False,
                        reaudit_after_close: bool = False, external_action: bool = False,
                        host_config: bool = False, land_emitted_event: bool = False,
                        preshipped_deliverable: bool = False, preshipped_commit: "str | None" = None,
                        settlement_sweep: bool = False, settlement_commits: "list | None" = None,
                        post_ship_observation: "dict | None" = None,
                        activation_gated_radius: "dict | None" = None,
                        prior_record: "dict | None" = None, prior_passes: int = 0,
                        on_decisions: "dict | None" = None,
                        evidence_sink=None,
                        readiness_sink=None, readiness_journal_silent: bool = False) -> str:
    """Thin host wrapper -> audit.build_audit_prompt (T-9248). Preserves the historical signature so
    cmd_audit* call-sites are unchanged; injects the 7 host-coupled prompt-section helpers (the engine
    reads no host global). The yitc.<symbol> test contracts (each helper individually replaceable on the
    host module) are honored because the host names are resolved here at call time. `prior_record`
    (T-9681): the prior saved audit record for this target+stage, threaded through so the engine renders
    the MONOTONIC per-pass re-audit section on pass N>=2 (None on pass 1 / non-absorption-loop kinds).
    `evidence_sink` (T-10741, SPEC-0168 rule 5): passed straight through — the TASK audit-post branch
    fills it with the evidence rows the packet COUNTED, so `cmd_audit` can record that set durably.
    `readiness_sink` / `readiness_journal_silent` (T-11977, SPEC-0036 §Packet preview): passed
    straight through — the `--preview` path supplies them so the engine renders the report-only
    packet-readiness block from the parts that one assembly pass already computed."""
    return audit.build_audit_prompt(
        task, stage, diff, extra, target_kind=target_kind, focus=focus,
        event_emit_only=event_emit_only, serve_deploy=serve_deploy,
        reaudit_after_close=reaudit_after_close, external_action=external_action,
        host_config=host_config, land_emitted_event=land_emitted_event,
        preshipped_deliverable=preshipped_deliverable, preshipped_commit=preshipped_commit,
        settlement_sweep=settlement_sweep, settlement_commits=settlement_commits,
        post_ship_observation=post_ship_observation,
        activation_gated_radius=activation_gated_radius,
        prior_record=prior_record,
        prior_passes=prior_passes,   # T-12288 (SPEC-0204 rule 8): the pass-1-vs-later round fork
        on_decisions=on_decisions,   # T-12289 (SPEC-0204 rule 3): the decided-residual projection
        evidence_sink=evidence_sink,
        readiness_sink=readiness_sink,
        readiness_journal_silent=readiness_journal_silent,
        repo_root=REPO_ROOT,   # T-11778: the checkout the collector-shape facts are read from
        yaml_dump_block=yaml_dump_block,
        latest_event_for=_latest_event_for,
        diff_touched_files=_diff_touched_files,
        norm_repo_path=_norm_repo_path,
        ac_probe_evidence_events_for=_ac_probe_evidence_events_for,
        cross_evidence_section_for=_cross_evidence_section_for,
        p8_carrier_section_for=_p8_carrier_section_for,
        spec_coverage_section=_spec_coverage_section,
        scenario_contract_section=_scenario_contract_section,
        build_referenced_files_section=_build_referenced_files_section)


def _build_referenced_files_section(task: dict) -> str:
    """T-0035: assemble ## Referenced files section для audit-pre prompt.

    Walks _extract_referenced_paths output, reads excerpt per-file under total cap,
    formats as code fences с per-file header. Returns "" если no refs (omit section).
    """
    paths = _extract_referenced_paths(task)
    if not paths:
        return ""
    blocks: list[str] = ["## Referenced files\n"]
    # T-11140: the shared budget runs on BOTH axes. A line-only total budget is defeated by long
    # lines (MEASURED: 2.4MB spent 80 of 3000 "remaining" lines), so a single fat artifact could put
    # megabytes into the prompt while every later path still looked affordable.
    remaining, remaining_b = AUDIT_MAX_REF_LINES_TOTAL, AUDIT_MAX_REF_BYTES_TOTAL
    for path in paths:
        rel = path.relative_to(REPO_ROOT)
        if remaining <= 0 or remaining_b <= 0:
            # NAMED, never silent — an omitted path must stay visibly present (anti-false-absent).
            blocks.append(f"### {rel}\n\n(omitted — total cap reached; the file IS present)\n")
            continue
        excerpt, used, used_b = _read_referenced_excerpt(path, remaining, remaining_b, label=str(rel))
        if not excerpt:
            continue
        blocks.append(f"### {rel}\n\n```\n{excerpt}\n```\n")
        remaining -= used
        remaining_b -= used_b
    return "\n".join(blocks)


def yaml_dump_block(items: list) -> str:
    """Format а list as а bulleted block для prompt readability."""
    if not items:
        return "(empty)"
    return "\n".join(f"- {item}" for item in items)


