# T-0361: filename-safe slug for an ad-hoc consult verdict (kebab + bare T-/D-/SPEC- ids — the
# shapes already present among the hand-authored decisions/*-audit-adhoc.yaml prior art).
ADHOC_SLUG_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9-]*$")


# T-9318 — auto-inline referenced corpus files into an ad-hoc consult prompt.
# `audit adhoc --read-corpus` (T-0713) used to give codex `-C <repo> -s read-only` file tooling,
# but the external auditor declines that tooling and asks for inline content (F-020), so the
# corpus-read mode was a no-op / ABORTed. Instead of relying on the tooling, scan the request text
# for referenced corpus paths and inline their content directly — reliable, no tooling needed.
INLINE_CORPUS_MAX_BYTES = 64 * 1024   # per-file cap — keep one runaway file from bloating the prompt
INLINE_CORPUS_MAX_FILES = 20          # cap the inlined set
# Path-like tokens: a slash-bearing path, OR a bare/relative name ending in an extension, OR a
# Capitalized extensionless filename (Makefile / LICENSE / Dockerfile — conventionally capitalized,
# so prose words are not swept). The fail-closed existence-under-REPO_ROOT gate filters the rest.
INLINE_CORPUS_PATH_RE = re.compile(r"[\w./\-]*/[\w./\-]+|[\w.\-]+\.[\w]+|\b[A-Z][A-Za-z]{2,}\b")

# T-9637 (X-0125): `audit adhoc --sweep-file` inlines EXPLICIT pre-computed mechanical sweeps
# (journal/git output). A sweep is bigger than a curated corpus file (a full git-log / journal-grep
# slice), so the per-file cap is larger than INLINE_CORPUS_MAX_BYTES; the set is count-capped the same.
INLINE_SWEEP_MAX_BYTES = 256 * 1024   # per-sweep cap — a journal/git sweep is larger than a corpus file
INLINE_SWEEP_MAX_FILES = 20           # cap the inlined sweep set


def _inline_corpus_files(request: str) -> tuple[str, list[str], int]:
    return audit._inline_corpus_files(request, INLINE_CORPUS_MAX_BYTES=INLINE_CORPUS_MAX_BYTES, INLINE_CORPUS_MAX_FILES=INLINE_CORPUS_MAX_FILES, INLINE_CORPUS_PATH_RE=INLINE_CORPUS_PATH_RE, REPO_ROOT=REPO_ROOT)


def _inline_sweep_files(paths) -> tuple[str, list[str], int, list[str]]:
    return audit._inline_sweep_files(paths, INLINE_SWEEP_MAX_BYTES=INLINE_SWEEP_MAX_BYTES, INLINE_SWEEP_MAX_FILES=INLINE_SWEEP_MAX_FILES)


