    return graph._graph_query_recurring(index, EVENTS_PATH=EVENTS_PATH, _capture_cluster_counts=_capture_cluster_counts, _capture_fingerprint_counts=_capture_fingerprint_counts, _discovery_stem_clusters=_discovery_stem_clusters)


